mapper.select:
SELECT 
FROM game_item_uses
WHERE game_id = #{gameId}
  AND account_id = #{accountId}
  AND item_id = #{itemId}
  AND slot = #{slot}
  AND status = 'reserved'
ORDER BY created_at DESC
LIMIT 1

mapper.update:
